CREATE TABLE subnet (
    id INTEGER PRIMARY KEY,
    `start` BLOB NOT NULL,
    `end` BLOB NOT NULL,
    `country` INTEGER NOT NULL,
    FOREIGN KEY(country) REFERENCES country(id)
);
CREATE INDEX subnet_idx ON subnet ("start", "end");

CREATE TABLE country (
    id INTEGER PRIMARY KEY,
    code TEXT NOT NULL,
    name TEXT NOT NULL,
    continent INTEGER NOT NULL,
    FOREIGN KEY(continent) REFERENCES continent(id)
);

CREATE TABLE continent (
    id INTEGER PRIMARY KEY,
    code TEXT NOT NULL,
    name TEXT NOT NULL
);

CREATE VIEW subnet_country
AS
SELECT
    `start`,
    `end`,
    country.code AS code,
    country.name AS country
FROM
    subnet
LEFT JOIN
    country ON subnet.country = country.id;

CREATE VIEW subnet_all
AS
SELECT
    `start`,
    `end`,
    country.code AS country_code,
    country.name AS country_name,
    continent.code AS continent_code,
    continent.name AS continent_name
FROM
    subnet
LEFT JOIN
    country ON subnet.country = country.id
LEFT JOIN
    continent ON country.continent = continent.id;

BEGIN TRANSACTION;
END TRANSACTION;
